insert into public.case_studies (slug, client, category, industry, summary, platform, duration, image, accent, icon, challenge, solution_short, tags, content, status, published_at)
values
  ('kabita-erp', 'Kabita Shooting & Online Store', 'ERP & Website', 'Retail & E-Commerce', 'A unified online store and custom ERP that put orders, inventory, and billing on one dashboard — replacing manual work with a single source of truth.', 'Web Application', '6 Months', '/images/portfolio/kabita.png', 'blue', 'ShoppingBag', 'Fragmented inventory tracking across retail and e-commerce channels caused stockouts and delayed order fulfillment.', 'We engineered a custom ERP seamlessly integrated with their online store, providing real-time inventory synchronization.', array['React', 'Node.js', 'PostgreSQL', 'AWS'], '{"overview":{"company":"Kabita is a fast-growing retail and e-commerce brand specializing in sports equipment and lifestyle apparel.","goals":["Centralize inventory management","Automate billing and order fulfillment","Create a high-converting e-commerce storefront"],"background":"Operating across multiple physical locations and a disjointed online store, the company faced significant operational friction. Data silos between the warehouse and the storefront led to overselling, delayed shipments, and massive manual data entry."},"challenges":{"description":"Fragmented systems severely bottlenecked growth. The lack of a single source of truth meant staff spent hours daily reconciling spreadsheets.","points":["Stockouts due to disconnected inventory data","Manual order processing resulting in high error rates","Poor mobile experience on the legacy storefront","Legacy monolithic PHP backend with no real-time database synchronization"]},"solution":{"approach":"We engineered a decoupled headless architecture separating the React frontend from a robust Node.js/PostgreSQL ERP backend, taking an API-first approach so it could effortlessly plug into third-party logistics and payment gateways. The UI was completely overhauled using a custom design system prioritizing accessibility, fast loading, and mobile-first conversions.","features":["Real-time inventory synchronization","Automated invoice generation","Multi-warehouse management dashboard","Headless CMS integration"]},"developmentProcess":{"methodology":"Agile Scrum (2-week sprints)","milestones":[{"title":"Discovery & Architecture","desc":"System blueprinting and database modeling."},{"title":"ERP Core Development","desc":"Building the inventory and billing microservices."},{"title":"Storefront Integration","desc":"Connecting the headless Next.js frontend to the ERP."},{"title":"UAT & Deployment","desc":"Rigorous testing and zero-downtime migration."}]},"results":{"businessImpact":"Increased order fulfillment speed by 40% and eliminated stock discrepancies.","kpis":[{"label":"Fulfillment Speed","value":"+40%"},{"label":"Inventory Errors","value":"-99%"},{"label":"Mobile Conversion","value":"+2.5x"}],"outcomes":["Page load times decreased by 60%, with API responses optimized to under 100ms","Completely eliminated manual data entry","Enabled expansion into two new physical locations","Zero downtime during peak holiday sales"]},"gallery":["/images/portfolio/kabita.png","/images/portfolio/kabita.png","/images/portfolio/kabita.png"],"testimonial":{"quote":"The unified ERP completely transformed our operations. We went from chaotic spreadsheet management to absolute clarity. Our online sales have never been smoother.","author":"CEO","position":"Founder & CEO","company":"Kabita Shooting","image":"https://i.pravatar.cc/150?img=12"}}'::jsonb, 'published', now()),
  
  ('yasyasvi-logistics', 'Yasyasvi', 'Custom ERP', 'Operations & Logistics', 'A tailored ERP with built-in tracking that gave the team real-time visibility across daily operations.', 'Web & Mobile App', '8 Months', '/images/portfolio/yasyasvi.png', 'cyan', 'Radar', 'Reliance on spreadsheets resulted in poor visibility into field operations and fleet tracking.', 'Developed a secure, cloud-based ERP equipped with real-time GPS tracking modules.', array['Next.js', 'Python', 'MongoDB', 'Azure'], '{"overview":{"company":"Yasyasvi is a logistics and field operations company.","goals":["Real-time fleet tracking","Automated dispatching","Predictive maintenance"],"background":"Managing hundreds of vehicles with legacy software resulted in massive operational overhead."},"challenges":{"description":"Reliance on spreadsheets and disconnected legacy systems resulted in poor visibility.","points":["Blind spots in field operations","Inefficient routing","Delayed reporting","No GPS integration API, running on a slow legacy database"]},"solution":{"approach":"Cloud-native microservices architecture on Azure, built to handle high-velocity telemetry data, with a utilitarian high-contrast dashboard designed for fast decision making.","features":["Live GPS Tracking","Automated Dispatching","Maintenance Alerts"]},"developmentProcess":{"methodology":"Agile Kanban","milestones":[{"title":"Telemetry Ingestion","desc":"Building the high-throughput data pipeline."},{"title":"Dashboard UI","desc":"Real-time mapping and dispatch controls."}]},"results":{"businessImpact":"Reduced operational overhead by 25% and improved tracking accuracy to 99.9%.","kpis":[{"label":"Tracking Accuracy","value":"99.9%"},{"label":"Op Overhead","value":"-25%"},{"label":"Dispatch Time","value":"-45%"}],"outcomes":["Sub-second telemetry updates handling 10k+ concurrent IoT connections","Optimized fuel consumption","Reduced fleet downtime"]},"gallery":["/images/portfolio/yasyasvi.png","/images/portfolio/yasyasvi.png"],"testimonial":{"quote":"Our dispatchers now have absolute god-view over the entire fleet. The ROI was realized within months.","author":"Operations Director","position":"VP Operations","company":"Yasyasvi","image":"https://i.pravatar.cc/150?img=33"}}'::jsonb, 'published', now()),
  
  ('aligans-social', 'Aligans Cricket', 'Social Media', 'Sports & Entertainment', 'A bold, consistent social presence and analytics platform that grew engagement.', 'SaaS Dashboard', '4 Months', '/images/portfolio/aligans.png', 'violet', 'Megaphone', 'Struggled to monetize their growing fanbase due to a lack of actionable audience data.', 'Implemented an automated social media management pipeline coupled with a bespoke fan analytics dashboard.', array['Vue', 'Laravel', 'Redis', 'Docker'], '{"overview":{"company":"Aligans Cricket is a premier sports entertainment franchise.","goals":["Centralize fan data","Automate content distribution","Monetize fan engagement"],"background":"A rapidly growing global fanbase required a scalable platform to manage interactions."},"challenges":{"description":"Struggled to monetize their growing fanbase due to inconsistent engagement.","points":["Fragmented audience data","Manual social posting","Low conversion on merch","API rate limits on legacy tools with no unified data warehouse"]},"solution":{"approach":"Event-driven architecture to process social webhook data in real-time, focused on heavy third-party API integrations and robust queuing, with a vibrant, high-energy UI matching the sports franchise brand.","features":["Unified Fan CRM","Automated Publishing","Sentiment Analytics"]},"developmentProcess":{"methodology":"Agile Scrum","milestones":[{"title":"API Integrations","desc":"Connecting to Meta, X, and YouTube APIs."},{"title":"Analytics Engine","desc":"Building the sentiment analysis module."}]},"results":{"businessImpact":"Grew social engagement by 300% and expanded global audience reach.","kpis":[{"label":"Engagement","value":"+300%"},{"label":"Audience Reach","value":"2M+"},{"label":"Merch Sales","value":"+85%"}],"outcomes":["Zero drops in webhook processing with real-time dashboard rendering","Created a new revenue stream via targeted fan marketing"]},"gallery":["/images/portfolio/aligans.png"],"testimonial":{"quote":"The analytics dashboard is a game-changer. We now know exactly what our fans want, when they want it.","author":"Marketing Head","position":"CMO","company":"Aligans","image":"https://i.pravatar.cc/150?img=44"}}'::jsonb, 'published', now())
on conflict (slug) do nothing;
